streams = re.findall(b'stream[\r\n]+(.*?)[\r\n]+endstream', content, re.DOTALL)
cmaps = {}
for s in streams:
    try:
        dec = zlib.decompress(s).decode('latin1')
        if 'beginbfrange' in dec or 'beginbfchar' in dec:
            for line in dec.split('\n'):
                # beginbfchar: <0001> <0020>
                for m in re.finditer(r'<([0-9a-fA-F]{4})>\s+<([0-9a-fA-F]{4})>', line):
                    src, dst = m.groups()
                    cmaps[src.lower()] = chr(int(dst, 16))
                # beginbfrange: <0001> <0005> <0020>
